"""Partition scenario ``initial_slots`` for Mantle session-start seeding."""

from __future__ import annotations

from pathlib import Path
from typing import Any, Dict, Mapping, Optional, Tuple

from rasa.builder.copilot.mcp_server.tools.scenario import check_slot_type_compatibility
from rasa.mantle.memory.field import MemoryField
from rasa.mantle.memory.schema import ProjectMemorySchema

_PROJECT_SLOT_PREFIX = "project."

_MEMORY_TYPE_TO_SLOT_TYPE: Dict[str, str] = {
    "text": "text",
    "bool": "bool",
    "float": "float",
    "list": "list",
    "categorical": "categorical",
    "strict_categorical": "categorical",
}


def load_project_memory_schema(project_path: Path) -> ProjectMemorySchema:
    """Load project ``memory.yml`` from a Rasa project root."""
    return ProjectMemorySchema.from_yaml(project_path / "memory.yml")


def project_field_name_for_initial_slot_key(
    key: str, project_fields: Mapping[str, MemoryField]
) -> Optional[str]:
    """Return the bare project field name when ``key`` refers to one, else ``None``."""
    if key in project_fields:
        return key
    if key.startswith(_PROJECT_SLOT_PREFIX):
        bare = key[len(_PROJECT_SLOT_PREFIX) :]
        if bare in project_fields:
            return bare
    return None


def partition_initial_slots(
    initial_slots: Mapping[str, Any],
    project_memory: ProjectMemorySchema,
) -> Tuple[Dict[str, Any], Dict[str, Any]]:
    """Split ``initial_slots`` into session-start metadata and post-start slot writes.

    Project fields marked ``seed: true`` are routed to session-start metadata
    using bare field names (matching channel gateways). All other entries stay
    on the tracker slot-injection path.

    Returns:
        A pair ``(session_start_metadata, post_session_start_slots)``.
    """
    session_start_metadata: Dict[str, Any] = {}
    post_session_start_slots: Dict[str, Any] = {}
    for key, value in initial_slots.items():
        field_name = project_field_name_for_initial_slot_key(key, project_memory.fields)
        if field_name is not None and project_memory.fields[field_name].seed:
            session_start_metadata[field_name] = value
        else:
            post_session_start_slots[key] = value
    return session_start_metadata, post_session_start_slots


def check_memory_field_value_compatibility(
    field_name: str, value: Any, field: MemoryField
) -> Optional[str]:
    """Return an error when ``value`` does not match ``field``, else ``None``."""
    if value is None:
        return None
    if field.type == "int":
        if not isinstance(value, int) or isinstance(value, bool):
            return (
                f"Project memory field '{field_name}' has type 'int' but "
                f"initial value {value!r} is incompatible."
            )
        return None
    slot_type = _MEMORY_TYPE_TO_SLOT_TYPE.get(field.type)
    if slot_type is not None:
        type_error = check_slot_type_compatibility(field_name, value, slot_type)
        if type_error is not None:
            return type_error.replace("Slot", "Project memory field", 1)
    if field.enum_values and value not in field.enum_values:
        return (
            f"Project memory field '{field_name}' value {value!r} is not one of "
            f"{field.enum_values!r}."
        )
    return None


def check_seed_initial_slot_errors(
    initial_slots: Mapping[str, Any],
    project_memory: ProjectMemorySchema,
) -> list[str]:
    """Validate ``initial_slots`` entries that map to ``seed: true`` project fields."""
    session_start_metadata, _ = partition_initial_slots(initial_slots, project_memory)
    errors: list[str] = []
    for field_name, value in session_start_metadata.items():
        field = project_memory.fields[field_name]
        type_error = check_memory_field_value_compatibility(field_name, value, field)
        if type_error is not None:
            errors.append(type_error)
    return errors
